// Verifies the HMAC signature Convex puts on every loan event
// (convex/automation/delivery.ts). Nothing downstream runs unless it matches.
const crypto = require('crypto');
const MAX_SKEW_SECONDS = 300;
const secret = $env.LENDLOOP_OUTBOUND_SIGNING_SECRET;
const reject = (status, reason) => [{ json: { ok: false, status, reason } }];
if (!secret) return reject(500, 'LENDLOOP_OUTBOUND_SIGNING_SECRET is not set');

const headers = $input.first().json.headers || {};
const timestamp = String(headers['x-lendloop-timestamp'] || '');
const signature = String(headers['x-lendloop-signature'] || '');
if (!/^\d{9,11}$/.test(timestamp)) return reject(401, 'missing or malformed timestamp');
if (Math.abs(Date.now() / 1000 - Number(timestamp)) > MAX_SKEW_SECONDS) return reject(401, 'stale timestamp');

// Verify the exact bytes Convex signed (raw body), not a re-serialized object.
const raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8');
const expected = Buffer.from('v1=' + crypto.createHmac('sha256', secret).update(`${timestamp}.${raw}`).digest('hex'));
const given = Buffer.from(signature);
if (expected.length !== given.length || !crypto.timingSafeEqual(expected, given)) return reject(401, 'signature mismatch');

let event;
try { event = JSON.parse(raw); } catch { return reject(400, 'body is not JSON'); }
if (!event.eventId || !event.type || !event.recipient?.email) return reject(400, 'missing required fields');

// Convex delivers at-least-once. Event ids we've already emailed are remembered
// in workflow static data (persisted only when an execution succeeds).
const seen = $getWorkflowStaticData('global').seenEvents || {};
return [{ json: { ok: true, duplicate: Boolean(seen[event.eventId]), event } }];

// Turns a loan event into an email. Uses only fields from the payload, which
// Convex already minimized (first names, tool name, dates, a deep link).
const e = $input.first().json.event;
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const fmt = (iso) => new Date(iso + 'T00:00:00Z').toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'UTC' });
const dates = e.loan.startDate === e.loan.endDate ? fmt(e.loan.startDate) : `${fmt(e.loan.startDate)} – ${fmt(e.loan.endDate)}`;
const tool = e.tool.name, them = e.counterpart.name, me = e.recipient.name;
const toLender = e.recipient.role === 'lender';

const T = {
  'loan.requested': [`${them} would like to borrow your ${tool}`, `${them} asked to borrow your ${tool} for ${dates}.`, 'Review the request'],
  'loan.approved': [`You're all set: ${tool} from ${them}`, `${them} approved your request to borrow the ${tool} for ${dates}. Their contact details are now on the loan in LendLoop, so you can arrange the pick-up.`, 'View your loan'],
  'loan.declined': [`Your request for the ${tool} wasn't approved`, `Your request to borrow the ${tool} for ${dates} wasn't approved this time. There may be other tools on the board that fit.`, 'Browse the board'],
  'loan.cancelled': toLender
    ? [`${them} cancelled their request for your ${tool}`, `${them} no longer needs the ${tool} for ${dates}. Nothing else to do.`, 'Open LendLoop']
    : [`Your booking for the ${tool} was cancelled`, `Your booking of the ${tool} for ${dates} was cancelled because the listing was removed.`, 'Browse the board'],
  'loan.returned': [`Thanks for returning the ${tool}`, `${them} confirmed the ${tool} is back. Thanks for being a good neighbor!`, 'Borrow something else'],
};
const [subject, line, cta] = T[e.type] || [`Update on the ${tool}`, `There's an update on your loan for ${dates}.`, 'Open LendLoop'];

const text = `Hi ${me},\n\n${line}\n\n${cta}: ${e.loan.url}\n\n— LendLoop\nYou're receiving this because you have an active request on LendLoop.`;
const html = `<div style="font-family:system-ui,sans-serif;max-width:520px;margin:auto;color:#1d2721">
  <p style="font-size:20px;font-weight:600;color:#2d6a4f">LendLoop</p>
  <p>Hi ${esc(me)},</p><p>${esc(line)}</p>
  <p><a href="${esc(e.loan.url)}" style="display:inline-block;background:#2d6a4f;color:#fff;padding:10px 18px;border-radius:10px;text-decoration:none">${esc(cta)}</a></p>
  <p style="color:#7d877f;font-size:12px">You're receiving this because you have an active request on LendLoop.</p></div>`;

return [{ json: { to: e.recipient.email, subject, text, html, eventId: e.eventId } }];

// Mark the event as handled (pruned after 7 days) so a Convex retry of the
// same eventId is acknowledged without emailing twice.
const sd = $getWorkflowStaticData('global');
sd.seenEvents = sd.seenEvents || {};
const now = Date.now();
for (const [id, at] of Object.entries(sd.seenEvents)) if (now - at > 7 * 24 * 3600 * 1000) delete sd.seenEvents[id];
const eventId = $('Compose email').first().json.eventId;
sd.seenEvents[eventId] = now;
return [{ json: { status: 'sent', eventId } }];
